    def __init__(self):
        self.valves = self.Valves()

    # =====================================================================
    # لایه پایگاه‌داده ممیزی SQLite و امضای اصالت (HMAC)
    # =====================================================================
    def _get_ledger_db_path(self) -> str:
        data_dir = os.environ.get("DATA_DIR", "/app/backend/data")
        try:
            os.makedirs(data_dir, exist_ok=True)
            test_path = os.path.join(data_dir, "mission_audit_ledger.db")
            with open(test_path, "a", encoding="utf-8"):
                pass
            return test_path
        except OSError:
            return os.path.join(tempfile.gettempdir(), "mission_audit_ledger.db")

    def _init_ledger_db(self) -> sqlite3.Connection:
        db_path = self._get_ledger_db_path()
        conn = sqlite3.connect(db_path, timeout=5.0)
        conn.execute("PRAGMA journal_mode=WAL;")
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS mission_confirmations (
                chat_id TEXT PRIMARY KEY,
                user_id TEXT NOT NULL,
                payload_hash TEXT NOT NULL,
                created_at TEXT NOT NULL
            )
            """
        )
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS mission_ledger (
                seq_id INTEGER PRIMARY KEY AUTOINCREMENT,
                mission_code TEXT UNIQUE,
                created_at TEXT NOT NULL,
                user_id TEXT NOT NULL,
                user_name TEXT NOT NULL,
                user_email TEXT NOT NULL,
                personnel_code TEXT NOT NULL,
                full_name TEXT NOT NULL,
                route_chain TEXT NOT NULL,
                total_payment INTEGER NOT NULL,
                total_funds INTEGER NOT NULL,
                advance_payment INTEGER NOT NULL,
                net_balance INTEGER NOT NULL,
                payload_json TEXT NOT NULL,
                hmac_sig TEXT NOT NULL
            )
            """
        )
        conn.commit()
        return conn

    def _compute_hmac_short(self, canonical_payload: str) -> str:
        secret = (self.valves.hmac_secret_key or "DEFAULT-KEY").encode("utf-8")
        digest = hmac.new(secret, canonical_payload.encode("utf-8"), hashlib.sha256).hexdigest().upper()
        return digest[:4]

    def _save_confirmation_state(self, chat_id: str, user_id: str, payload_hash: str) -> None:
        if not chat_id:
            return
        conn = self._init_ledger_db()
        try:
            now_iso = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
            conn.execute(
                """
                INSERT INTO mission_confirmations (chat_id, user_id, payload_hash, created_at)
                VALUES (?, ?, ?, ?)
                ON CONFLICT(chat_id) DO UPDATE SET
                    user_id=excluded.user_id,
                    payload_hash=excluded.payload_hash,
                    created_at=excluded.created_at
                """,
                (chat_id, user_id, payload_hash, now_iso),
            )
            conn.commit()
        finally:
            conn.close()

    def _has_confirmation_state(self, chat_id: str) -> bool:
        if not chat_id:
            return True
        conn = self._init_ledger_db()
        try:
            row = conn.execute(
                "SELECT 1 FROM mission_confirmations WHERE chat_id = ?",
                (chat_id,),
            ).fetchone()
            return row is not None
        finally:
            conn.close()

    def _clear_confirmation_state(self, chat_id: str) -> None:
        if not chat_id:
            return
        conn = self._init_ledger_db()
        try:
            conn.execute("DELETE FROM mission_confirmations WHERE chat_id = ?", (chat_id,))
            conn.commit()
        finally:
            conn.close()

    def _record_mission_ledger(
        self,
        user_info: Dict[str, str],
        rpt: Dict[str, Any],
    ) -> str:
        conn = self._init_ledger_db()
        try:
            now_iso = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
            compact_record = {
                "personnel_code": rpt["personnel_code"],
                "full_name": rpt["full_name"],
                "grade_display": rpt["grade_display"],
                "route_chain": rpt["route_chain"],
                "origin_departure": rpt["origin_departure_display"],
                "origin_arrival": rpt["origin_arrival_display"],
                "total_payment": rpt["total_payment"],
                "total_funds": rpt["total_funds"],
                "advance_payment": rpt["advance_payment"],
                "net_balance": rpt["net_balance"],
                "warnings": rpt["warnings"],
            }
            payload_str = json.dumps(compact_record, ensure_ascii=False, sort_keys=True)
            cur = conn.execute(
                """
                INSERT INTO mission_ledger (
                    mission_code, created_at, user_id, user_name, user_email,
                    personnel_code, full_name, route_chain,
                    total_payment, total_funds, advance_payment, net_balance,
                    payload_json, hmac_sig
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    None,
                    now_iso,
                    user_info["id"],
                    user_info["name"],
                    user_info["email"],
                    rpt["personnel_code"],
                    rpt["full_name"],
                    rpt["route_chain"],
                    int(rpt["total_payment"]),
                    int(rpt["total_funds"]),
                    int(rpt["advance_payment"]),
                    int(rpt["net_balance"]),
                    payload_str,
                    "PENDING",
                ),
            )
            seq_id = int(cur.lastrowid)
            canonical = (
                f"{seq_id}|{user_info['id']}|{rpt['personnel_code']}|"
                f"{rpt['total_payment']}|{rpt['total_funds']}|{rpt['advance_payment']}|{rpt['net_balance']}"
            )
            sig4 = self._compute_hmac_short(canonical)
            mission_code = f"MS-1405-{seq_id:04d}-{sig4}"
            conn.execute(
                "UPDATE mission_ledger SET mission_code = ?, hmac_sig = ? WHERE seq_id = ?",
                (mission_code, sig4, seq_id),
            )
            conn.commit()
            return mission_code
        finally:
            conn.close()

    @staticmethod
    def _extract_user_info(user_obj: Optional[Dict[str, Any]]) -> Dict[str, str]:
        if not isinstance(user_obj, dict):
            return {"id": "نامشخص", "name": "نامشخص", "email": "نامشخص", "role": "user"}
        return {
            "id": str(user_obj.get("id") or "نامشخص"),
            "name": str(user_obj.get("name") or "نامشخص"),
            "email": str(user_obj.get("email") or "نامشخص"),
            "role": str(user_obj.get("role") or "user").lower(),
        }

    # =====================================================================
    # توابع کمکی داخلی و پاک‌سازی امنیتی ورودی‌ها
    # =====================================================================
    @staticmethod
    def _norm_digits(text: Any) -> str:
        if text is None:
            return ""
        trans = str.maketrans("۰۱۲۳۴۵۶۷۸۹٠١٢٣٤٥٦٧٨٩", "01234567890123456789")
        return str(text).translate(trans).strip()

    def _sanitize_personnel_code(self, raw: Any) -> str:
        code = self._norm_digits(raw)
        if not re.fullmatch(r"\d{1,12}", code):
            raise ValueError("کد پرسنلی باید صرفاً شامل ۱ تا ۱۲ رقم باشد.")
        return code

    def _sanitize_full_name(self, raw: Any) -> str:
        name = re.sub(r"\s+", " ", str(raw or "")).strip()
        if not name or len(name) > 60:
            raise ValueError("نام و نام خانوادگی باید بین ۲ تا ۶۰ کاراکتر باشد.")
        if not re.fullmatch(r"[\u0600-\u06FF\u200c\s\-]+", name):
            raise ValueError("نام و نام خانوادگی باید صرفاً شامل حروف فارسی باشد (بدون عدد، علامت یا متن اضافه).")
        return name

    def _to_non_negative_float(self, val: Any, field_label_fa: str, default: float = 0.0) -> float:
        if val is None or str(val).strip() == "":
            return default
        s = self._norm_digits(val).replace(",", "").replace("٬", "").replace("ریال", "").replace("تومان", "").strip()
        try:
            num = float(s)
        except ValueError:
            raise ValueError(f"مقدار عددی «{field_label_fa}» نامعتبر است.")
        if num < 0:
            raise ValueError(f"مقدار «{field_label_fa}» نمی‌تواند منفی باشد.")
        return num

    def _to_non_negative_int(self, val: Any, field_label_fa: str, default: int = 0) -> int:
        f = self._to_non_negative_float(val, field_label_fa, float(default))
        return int(round(f))

    @staticmethod
    def _round_half_up(value: float) -> int:
        return int(Decimal(str(value)).quantize(Decimal("1"), rounding=ROUND_HALF_UP))

    @staticmethod
    def _fmt_rial(amount: Union[int, float]) -> str:
        return f"{int(round(amount)):,}"

    def _normalize_grade(self, raw: str) -> str:
        s = self._norm_digits(raw).upper().replace("کلاس", "").replace("گرید", "").replace("رده", "").strip()
        class_map = {"1": "A", "2": "B", "3": "C", "4": "D", "5": "E", "6": "F"}
        if s in class_map:
            return class_map[s]
        for k in ["A", "B", "C", "D", "E", "F"]:
            if s == k:
                return k
        role_map = {
            "مدیرعامل": "A", "مدیر عامل": "A", "معاون": "A", "معاونت": "A",
            "مشاور": "B", "مدیر": "B",
            "سرپرست": "C",
            "کارشناس": "D",
            "کارمند": "E",
            "کارگر": "F",
        }
        for rk, gv in role_map.items():
            if rk in str(raw):
                return gv
        raise ValueError(f"کلاس یا رده شغلی «{raw}» نامعتبر است. مقادیر مجاز: کلاس ۱ تا ۶ یا عنوان سطح شغلی.")

    def _normalize_vehicle(self, raw: str) -> Tuple[str, str, bool]:
        s = self._norm_digits(raw).strip()
        sl = s.lower()
        if not sl:
            raise ValueError("نوع وسیله نقلیه مشخص نشده است.")
        if any(w in sl for w in ["خودرو شرکت", "ماشین شرکت", "خودروی شرکت", "سواری شرکت", "شرکتی", "company_car"]):
            disp = "خودرو شرکت" if "company" in sl else s
            return "CAR", f"{disp} (معادل سواری)", True
        if any(w in sl for w in ["آژانس", "اژانس", "agency"]):
            disp = "آژانس" if sl == "agency" else s
            return "CAR", f"{disp} (معادل سواری)", False
        if sl in ("car", "سواری", "خودرو شخصی", "خودروی شخصی", "ماشین شخصی", "ماشین", "تاکسی برون شهری"):
            return "CAR", ("سواری" if sl == "car" else s), False
        if any(w in sl for w in ["هواپیما", "پرواز", "plane", "flight", "air"]):
            return "PLANE", "هواپیما", False
        if any(w in sl for w in ["قطار", "train", "rail"]):
            return "TRAIN", "قطار", False
        if "bus_night" in sl or ("اتوبوس" in sl and "شب" in sl):
            return "BUS_NIGHT", "اتوبوس شب", False
        if "bus_day" in sl or "اتوبوس" in sl or "bus" in sl:
            return "BUS_DAY", "اتوبوس روز", False
        raise ValueError(
            f"نوع وسیله نقلیه «{raw}» در جدول ضرایب تعریف نشده است. "
            "مقادیر مجاز: سواری، خودرو شرکت، آژانس، هواپیما، قطار، اتوبوس روز، اتوبوس شب."
        )

    def _normalize_transport_payer(self, raw: str) -> str:
        s = self._norm_digits(raw).strip().lower()
        if not s or any(w in s for w in ["company", "شرکت", "اداره", "تامین", "تأمین"]):
            return "company"
        if any(w in s for w in ["personal_car", "خودرو شخصی", "خودروی شخصی", "ماشین شخصی"]):
            return "personal_car"
        if any(w in s for w in ["personal", "شخص", "خودم", "مامور", "مأمور"]):
            return "personal"
        raise ValueError(f"مقدار پرداخت‌کننده وسیله نقلیه «{raw}» نامعتبر است. مقادیر مجاز: شرکت، شخص، خودروی شخصی.")

    def _normalize_accommodation_type(self, raw: str) -> str:
        s = self._norm_digits(raw).strip().lower()
        if not s or any(w in s for w in ["none", "بدون", "نداشت", "ندار"]):
            return "none"
        if any(w in s for w in ["company_guesthouse", "مهمانسرا", "اقامتگاه شرکت", "خوابگاه شرکت", "شرکتی"]):
            return "company_guesthouse"
        if any(w in s for w in ["hotel", "هتل"]):
            return "hotel"
        if any(w in s for w in ["personal_group", "شخصی گروهی", "گروهی", "مشترک"]):
            return "personal_group"
        if any(w in s for w in ["personal_individual", "شخصی انفرادی", "انفرادی", "شخصی", "منزل", "سوئیت"]):
            return "personal_individual"
        raise ValueError(
            f"نوع محل اسکان «{raw}» نامعتبر است. مقادیر مجاز: بدون اسکان، هتل، مهمانسرای شرکت، اسکان شخصی انفرادی، اسکان شخصی گروهی."
        )

    def _normalize_accommodation_payer(self, raw: str) -> str:
        s = self._norm_digits(raw).strip().lower()
        if not s or any(w in s for w in ["company", "شرکت", "اداره"]):
            return "company"
        if any(w in s for w in ["personal", "شخص", "خودم", "مامور", "مأمور"]):
            return "personal"
        raise ValueError(f"مقدار پرداخت‌کننده اسکان «{raw}» نامعتبر است. مقادیر مجاز: شرکت یا شخص.")

    def _normalize_contract_type(self, raw: str) -> str:
        s = self._norm_digits(raw).strip().lower()
        if not s or any(w in s for w in ["full_time", "تمام", "رسمی", "قراردادی", "عادی"]):
            return "full_time"
        if any(w in s for w in ["permanent_mission", "دائم", "دايم"]):
            return "permanent_mission"
        if any(w in s for w in ["part_time", "نیمه", "نيمه"]):
            return "part_time"
        if any(w in s for w in ["project", "پروژه"]):
            return "project"
        raise ValueError(f"نوع قرارداد «{raw}» نامعتبر است. مقادیر مجاز: تمام‌وقت، نیمه‌وقت، پروژه‌ای، دائم‌المأمور.")

    def _get_pair_coefficient(self, v1: str, v2: str) -> float:
        key = "|".join(sorted([v1, v2]))
        if key not in VEHICLE_PAIR_COEFFICIENTS:
            raise ValueError("ضریب ترکیب وسایل نقلیه انتخاب‌شده در جدول نرخ‌ها یافت نشد.")
        return float(VEHICLE_PAIR_COEFFICIENTS[key])

    def _parse_shamsi_date(self, shamsi_str: str) -> Tuple[str, datetime]:
        s = self._norm_digits(shamsi_str).replace("-", "/").strip()
        parts = s.split("/")
        if len(parts) != 3:
            raise ValueError(f"قالب تاریخ شمسی «{shamsi_str}» نامعتبر است. نمونه صحیح: 1405/06/11")
        y, m, d = int(parts[0]), int(parts[1]), int(parts[2])
        key = f"{y:04d}/{m:02d}/{d:02d}"
        if key not in CALENDAR_1405:
            raise ValueError(f"تاریخ «{key}» خارج از دامنه تقویم سال ۱۴۰۵ (1405/01/01 تا 1405/12/29) است.")
        greg_str = CALENDAR_1405[key][0]
        return key, datetime.strptime(greg_str, "%Y-%m-%d")

    def _parse_shamsi_datetime(self, dt_str: str) -> Tuple[str, datetime]:
        s = self._norm_digits(dt_str).replace("T", " ").strip()
        parts = s.split()
        if len(parts) != 2:
            raise ValueError(f"قالب تاریخ و ساعت «{dt_str}» نامعتبر است. نمونه صحیح: 1405/06/11 23:00")
        sh_key, g_date = self._parse_shamsi_date(parts[0])
        t_parts = parts[1].split(":")
        if len(t_parts) < 2:
            raise ValueError(f"قالب ساعت «{parts[1]}» نامعتبر است. نمونه صحیح: 08:30")
        hh, mm = int(t_parts[0]), int(t_parts[1])
        ss = int(t_parts[2]) if len(t_parts) >= 3 else 0
        if hh == 24 and mm == 0 and ss == 0:
            return f"{sh_key} 24:00", g_date + timedelta(days=1)
        if not (0 <= hh <= 23 and 0 <= mm <= 59 and 0 <= ss <= 59):
            raise ValueError(f"مقدار ساعت «{parts[1]}» نامعتبر است.")
        return f"{sh_key} {hh:02d}:{mm:02d}", g_date + timedelta(hours=hh, minutes=mm, seconds=ss)

    def _greg_to_shamsi_info(self, g_date: datetime) -> Optional[Tuple[str, List[Any]]]:
        g_str = g_date.strftime("%Y-%m-%d")
        for sh_key, info in CALENDAR_1405.items():
            if info[0] == g_str:
                return sh_key, info
        return None

    def _is_non_working_date(self, g_date: datetime) -> bool:
        pair = self._greg_to_shamsi_info(g_date)
        if not pair:
            return False
        _, inf = pair
        return (inf[2] == 1) or (self.valves.include_fridays_as_holiday and inf[3] == 1)

    @staticmethod
    def _format_holiday_label(sh_key: str, info: List[Any]) -> str:
        weekday = info[1]
        is_off = info[2] == 1
        is_fri = info[3] == 1
        occasion = (info[4] or "").strip()
        if is_off and occasion:
            return f"{sh_key} ({weekday} - {occasion})"
        if is_fri and not is_off:
            return f"{sh_key} (جمعه)"
        if is_off:
            return f"{sh_key} ({weekday} - تعطیل رسمی)"
        return f"{sh_key} ({weekday})"

    def _weighted_hours(self, start_dt: datetime, end_dt: datetime) -> float:
        if end_dt < start_dt:
            raise ValueError("زمان پایان حرکت نمی‌تواند قبل از زمان شروع حرکت باشد.")
        if end_dt == start_dt:
            return 0.0
        total_wh = 0.0
        cur = start_dt
        while cur < end_dt:
            day_start = datetime(cur.year, cur.month, cur.day)
            matched = False
            for h1, h2, coef in TIME_BRACKETS:
                b_start = day_start + timedelta(hours=h1)
                b_end = day_start + timedelta(hours=h2)
                if b_start <= cur < b_end:
                    seg_end = min(end_dt, b_end)
                    hrs = (seg_end - cur).total_seconds() / 3600.0
                    total_wh += hrs * coef
                    cur = seg_end
                    matched = True
                    break
            if not matched:
                raise ValueError("خطای داخلی در تطبیق بازه زمانی مسیر رخ داد.")
        return total_wh

    def _compute_holidays(self, start_dt: datetime, end_dt: datetime, d_total: int) -> Tuple[float, List[str]]:
        if end_dt <= start_dt or d_total <= 0:
            return 0.0, []
        holiday_hours = 0.0
        touched_days: List[str] = []
        cur = start_dt
        while cur < end_dt:
            day_start = datetime(cur.year, cur.month, cur.day)
            next_day = day_start + timedelta(days=1)
            seg_end = min(end_dt, next_day)
            info_pair = self._greg_to_shamsi_info(day_start)
            if info_pair is None:
                raise ValueError("یکی از تاریخ‌های سفر خارج از تقویم سال ۱۴۰۵ است.")
            sh_key, info = info_pair
            is_off = info[2] == 1
            is_fri = info[3] == 1
            is_hol = is_off or (self.valves.include_fridays_as_holiday and is_fri)
            if is_hol:
                hrs = (seg_end - cur).total_seconds() / 3600.0
                holiday_hours += hrs
                label = self._format_holiday_label(sh_key, info)
                if label not in touched_days:
                    touched_days.append(label)
            cur = seg_end

        if self.valves.holiday_counting_mode == "full_day_if_touched":
            d_holiday = float(min(len(touched_days), d_total))
        else:
            d_holiday = min(holiday_hours / 24.0, float(d_total))
        return d_holiday, touched_days

    def _count_eligible_meals(self, start_dt: datetime, end_dt: datetime) -> Dict[str, int]:
        counts = {"breakfast": 0, "lunch": 0, "dinner": 0}
        start_day = start_dt.date()
        end_day = end_dt.date()
        st_min = start_dt.hour * 60 + start_dt.minute
        en_min = end_dt.hour * 60 + end_dt.minute

        if start_day == end_day:
            if self.valves.single_day_meal_mode == "strict_pdf_both":
                if st_min <= 6 * 60 and en_min >= 9 * 60:
                    counts["breakfast"] += 1
                if st_min <= 12 * 60 and en_min >= 15 * 60:
                    counts["lunch"] += 1
                if st_min <= 19 * 60 and en_min >= 22 * 60:
                    counts["dinner"] += 1
            else:
                if st_min <= 9 * 60 and en_min >= 6 * 60:
                    counts["breakfast"] += 1
                if st_min <= 15 * 60 and en_min >= 12 * 60:
                    counts["lunch"] += 1
                if st_min <= 22 * 60 and en_min >= 19 * 60:
                    counts["dinner"] += 1
        else:
            if st_min <= 6 * 60:
                counts["breakfast"] += 1
            if st_min <= 12 * 60:
                counts["lunch"] += 1
            if st_min <= 19 * 60:
                counts["dinner"] += 1

            middle_days = (end_day - start_day).days - 1
            if middle_days > 0:
                counts["breakfast"] += middle_days
                counts["lunch"] += middle_days
                counts["dinner"] += middle_days

            if en_min >= 9 * 60:
                counts["breakfast"] += 1
            if en_min >= 15 * 60:
                counts["lunch"] += 1
            if en_min >= 22 * 60:
                counts["dinner"] += 1

        return counts

    def _lookup_city_distance(self, origin: str, destination: str) -> Optional[int]:
        orig = origin.strip()
        dest = destination.strip()
        if orig == "اصفهان":
            if dest in DISTANCES_FROM_ISFAHAN:
                return DISTANCES_FROM_ISFAHAN[dest]
            for k, v in DISTANCES_FROM_ISFAHAN.items():
                if k in dest or dest in k:
                    return v
        if dest == "اصفهان":
            if orig in DISTANCES_FROM_ISFAHAN:
                return DISTANCES_FROM_ISFAHAN[orig]
            for k, v in DISTANCES_FROM_ISFAHAN.items():
                if k in orig or orig in k:
                    return v
        return None

    def _parse_legs(self, legs_json: str) -> List[Dict[str, Any]]:
        legs_raw = json.loads(legs_json) if isinstance(legs_json, str) else legs_json
        if not isinstance(legs_raw, list) or len(legs_raw) == 0:
            raise ValueError("حداقل یک مرحله سفر برای محاسبه الزامی است.")
        parsed_legs = []
        prev_dest = self.valves.default_origin_city
        for idx, lg in enumerate(legs_raw):
            orig = str(lg.get("origin") or "").strip()
            if not orig:
                orig = self.valves.default_origin_city if idx == 0 else prev_dest
            dest = str(lg.get("destination") or "").strip()
            if not dest:
                raise ValueError(f"مقصد مرحله {idx + 1} مشخص نشده است.")
            if not lg.get("depart") or not lg.get("arrive"):
                raise ValueError(f"تاریخ و ساعت حرکت یا رسیدن مرحله {idx + 1} ناقص است.")
            dep_sh, dep_dt = self._parse_shamsi_datetime(str(lg["depart"]))
            arr_sh, arr_dt = self._parse_shamsi_datetime(str(lg["arrive"]))
            if arr_dt < dep_dt:
                raise ValueError(f"زمان رسیدن مرحله {idx + 1} قبل از زمان حرکت آن است.")
            if parsed_legs and dep_dt < parsed_legs[-1]["arr_dt"]:
                raise ValueError(f"زمان حرکت مرحله {idx + 1} قبل از زمان رسیدن مرحله قبلی است.")
            v_code, v_label, is_comp_car = self._normalize_vehicle(str(lg.get("vehicle") or ""))
            dur_h = (arr_dt - dep_dt).total_seconds() / 3600.0
            wh = self._weighted_hours(dep_dt, arr_dt)
            official_d = self._lookup_city_distance(orig, dest)
            lg_dist = lg.get("distance_km")
            if official_d is not None:
                lg_dist_val: Optional[float] = float(official_d)
            elif lg_dist is not None and str(lg_dist).strip() != "":
                lg_dist_val = self._to_non_negative_float(lg_dist, f"فاصله مرحله {idx + 1}")
            else:
                lg_dist_val = None
            parsed_legs.append({
                "origin": orig,
                "destination": dest,
                "depart": dep_sh,
                "arrive": arr_sh,
                "dep_dt": dep_dt,
                "arr_dt": arr_dt,
                "vehicle_code": v_code,
                "vehicle_label": v_label,
                "is_company_car": is_comp_car,
                "hours": dur_h,
                "weighted_hours": wh,
                "distance_km": lg_dist_val,
                "official_distance_km": float(official_d) if official_d is not None else None,
            })
            prev_dest = dest
        return parsed_legs

    def _evaluate_office_overlap(
        self,
        trip_start_dt: datetime,
        trip_end_dt: datetime,
        worked_at_company_on_start_day: Optional[bool],
        worked_at_company_on_end_day: Optional[bool],
    ) -> Tuple[datetime, datetime, str, str, str]:
        start_day_dt = datetime(trip_start_dt.year, trip_start_dt.month, trip_start_dt.day)
        end_is_exact_midnight = (trip_end_dt.hour == 0 and trip_end_dt.minute == 0 and trip_end_dt.second == 0)
        eff_end_cal_dt = (trip_end_dt - timedelta(days=1)) if end_is_exact_midnight else trip_end_dt
        end_day_dt = datetime(eff_end_cal_dt.year, eff_end_cal_dt.month, eff_end_cal_dt.day)

        start_day_is_workday = not self._is_non_working_date(start_day_dt)
        end_day_is_workday = not self._is_non_working_date(end_day_dt)
        multi_calendar_days = end_day_dt.date() > start_day_dt.date()

        if worked_at_company_on_start_day is not None:
            excl_start = bool(worked_at_company_on_start_day) and multi_calendar_days and start_day_is_workday
        else:
            excl_start = (
                self.valves.auto_exclude_office_workdays
                and multi_calendar_days
                and start_day_is_workday
                and (trip_start_dt.hour >= int(self.valves.office_end_hour))
            )

        if worked_at_company_on_end_day is not None:
            excl_end = bool(worked_at_company_on_end_day) and multi_calendar_days and end_day_is_workday and (not end_is_exact_midnight)
        else:
            excl_end = (
                self.valves.auto_exclude_office_workdays
                and multi_calendar_days
                and end_day_is_workday
                and (not end_is_exact_midnight)
                and (
                    trip_end_dt.hour < int(self.valves.early_return_workday_hour)
                    or (trip_end_dt.hour == int(self.valves.early_return_workday_hour) and trip_end_dt.minute == 0)
                )
            )

        daily_eff_start = trip_start_dt
        daily_eff_end = trip_end_dt
        notes: List[str] = []

        start_pair = self._greg_to_shamsi_info(start_day_dt)
        end_pair = self._greg_to_shamsi_info(end_day_dt)
        start_wd = start_pair[1][1] if start_pair else ""
        end_wd = end_pair[1][1] if end_pair else ""
        start_sh = start_pair[0] if start_pair else ""
        end_sh = end_pair[0] if end_pair else ""

        if excl_start:
            daily_eff_start = start_day_dt + timedelta(days=1)
            notes.append(
                f"روز شروع ({start_wd} {start_sh}) روز حضور در شرکت بوده و از بخش روزانه کسر شد (حق مسیر رفت پرداخت می‌شود)"
            )
        if excl_end:
            daily_eff_end = end_day_dt
            notes.append(
                f"روز بازگشت ({end_wd} {end_sh}) روز حضور در شرکت بوده و حق مأموریت روزانه ندارد (حق مسیر برگشت پرداخت می‌شود)"
            )

        summary = "؛ ".join(notes) if notes else "هم‌پوشانی با روز حضور در شرکت وجود ندارد"
        return daily_eff_start, daily_eff_end, summary, start_wd, end_wd

