    def _build_markdown_report(self, rpt: Dict[str, Any]) -> str:
        bal = rpt["net_balance"]
        bal_note = "قابل پرداخت به مأمور" if bal >= 0 else "قابل استرداد توسط مأمور"

        legs_md = [
            "| مرحله | مسیر | حرکت | رسیدن | وسیله | ساعت واقعی | ساعت وزنی | حق مسیر (ریال) |",
            "|---:|---|---|---|---|---:|---:|---:|",
        ]
        for idx, lg in enumerate(rpt["legs_detail"], 1):
            legs_md.append(
                f"| {idx} | {lg['origin']} ← {lg['destination']} | {lg['depart']} | {lg['arrive']} | "
                f"{lg['vehicle_label']} | {lg['hours']:.2f} | {lg['weighted_hours']:.2f} | {self._fmt_rial(lg['leg_pay'])} |"
            )

        lines = [
            f"### فرم گزارش محاسبه حق مأموریت و صورت هزینه‌ها (کد یکتا: `{rpt['mission_code']}`)",
            f"**ثبت‌کننده در سامانه:** {rpt['registrant_display']} | **وضعیت:** خوداظهاری (نیازمند تطبیق در امور مالی)",
            "",
            "| مشخصه | مقدار | مشخصه | مقدار |",
            "|---|---|---|---|",
            f"| **کد پرسنلی** | {rpt['personnel_code']} | **نام و نام خانوادگی** | {rpt['full_name']} |",
            f"| **کلاس شغلی / کلاس مؤثر** | {rpt['grade_display']} | **نوع سفر** | {rpt['trip_group_label']} |",
            f"| **مبدأ ← مقصد(ها)** | {rpt['route_chain']} | **فاصله یک‌طرفه / رفت‌وبرگشت** | {rpt['one_way_km']:,.0f} / {rpt['round_trip_km']:,.0f} کیلومتر |",
            f"| **مبنای حقوق (پایه + سنوات)** | {self._fmt_rial(rpt['salary_base'])} ریال | **نرخ روزانه / نرخ ساعتی** | {self._fmt_rial(rpt['daily_rate'])} / {self._fmt_rial(rpt['hourly_rate'])} ریال |",
            f"| **حرکت از مبدأ** | {rpt['origin_departure_display']} | **بازگشت به مبدأ** | {rpt['origin_arrival_display']} |",
            f"| **مدت حضور در مقصد** | {rpt['presence_hours']:.2f} ساعت ({rpt['presence_days']:.2f} روز) | **تعداد شب اقامت واقعی در مقصد** | {rpt['nights']} شب |",
            f"| **تعداد روز مبنای محاسبه** | {rpt['d_total']} روز (عادی: {rpt['d_normal']:.2f} / تعطیل: {rpt['d_holiday']:.2f}) | **تعطیلات و جمعه‌ها** | {rpt['holidays_text']} |",
            f"| **وضعیت حضور در شرکت (بند ۵-۴-۱-۳)** | {rpt['office_overlap_summary']} | **وسیله سفر / پرداخت‌کننده** | {rpt['vehicle_summary']} ({rpt['transport_payer_label']}) |",
            f"| **محل اسکان / پرداخت‌کننده** | {rpt['accommodation_type_label']} ({rpt['accommodation_payer_label']}) | **وضعیت صبحانه هتل** | {rpt['hotel_breakfast_label']} |",
            f"| **وعده‌های استحقاقی** | صبحانه: {rpt['meals']['breakfast']} ، ناهار: {rpt['meals']['lunch']} ، شام: {rpt['meals']['dinner']} | **تاکسی و تردد درون‌شهری قابل پرداخت** | {self._fmt_rial(rpt['intracity_payable'])} ریال |",
            f"| **سقف تجمیعی غذا / فاکتور غذا** | {self._fmt_rial(rpt['meal_cap_total'])} / {self._fmt_rial(rpt['meal_invoice_total'])} ریال | **علی‌الحساب پرداخت‌شده** | {self._fmt_rial(rpt['advance_payment'])} ریال |",
            "",
            "#### جزئیات مراحل مسیر",
            *legs_md,
            "",
            "#### خلاصه مالی (ارقام به ریال)",
            "| شرح ردیف مالی | مبلغ (ریال) |",
            "|---|---:|",
            f"| حق حضور و بخش روزانه | {self._fmt_rial(rpt['daily_mission_pay'])} |",
            f"| حق مسیر رفت و برگشت | {self._fmt_rial(rpt['route_pay'])} |",
            f"| **جمع فوق‌العاده حق مأموریت** | **{self._fmt_rial(rpt['total_payment'])}** |",
            f"| هزینه تغذیه قابل بازپرداخت (سقف تجمیعی: {self._fmt_rial(rpt['meal_cap_total'])}) | {self._fmt_rial(rpt['meal_payable'])} |",
            f"| هزینه اسکان قابل بازپرداخت | {self._fmt_rial(rpt['accommodation_payable'])} |",
            f"| هزینه ایاب‌وذهاب قابل بازپرداخت (کیلومتری شخصی و تردد درون‌شهری) | {self._fmt_rial(rpt['transport_payable'])} |",
            f"| سایر هزینه‌های جانبی مجاز با فاکتور (بدون اضافه‌کاری) | {self._fmt_rial(rpt['other_expenses_payable'])} |",
            f"| **جمع هزینه‌های جانبی قابل بازپرداخت** | **{self._fmt_rial(rpt['total_funds'])}** |",
            f"| جمع ناخالص قابل پرداخت | {self._fmt_rial(rpt['gross_payable'])} |",
            f"| کسر می‌شود: علی‌الحساب پرداخت‌شده | {self._fmt_rial(rpt['advance_payment'])} |",
            f"| **مانده تسویه نهایی ({bal_note})** | **{self._fmt_rial(rpt['net_balance'])}** |",
        ]
        if rpt["warnings"]:
            lines.append("")
            lines.append("**هشدارها و نکات کنترلی:**")
            for w in rpt["warnings"]:
                lines.append(f"- {w}")
        return "\n".join(lines)

    # =====================================================================
    # ابزار عمومی ۱: استعلام تقویم ۱۴۰۵ و مسافت شهرها
    # =====================================================================
    async def lookup_calendar_and_distance(
        self,
        start_shamsi_date: str,
        end_shamsi_date: str,
        destination_city: str,
        origin_city: str = "",
        __event_emitter__: Optional[Callable] = None,
    ) -> str:
        """
        استعلام نام دقیق روز هفته تمام تاریخ‌های بازه سفر، تعطیلات رسمی و جمعه‌های سال ۱۴۰۵ و مسافت بین مبدأ و مقصد.
        قانون: هرگز روز هفته یا تعطیلی هیچ تاریخی را حدس نزن؛ همیشه از خروجی این ابزار استفاده کن و پاسخ خود را به فارسی خالص بنویس.

        :param start_shamsi_date: تاریخ شمسی شروع سفر (مثلاً 1405/06/11)
        :param end_shamsi_date: تاریخ شمسی پایان سفر (مثلاً 1405/06/13)
        :param destination_city: نام شهر مقصد (مثلاً تهران)
        :param origin_city: نام شهر مبدأ (در صورت خالی بودن، اصفهان در نظر گرفته می‌شود)
        :return: اطلاعات دقیق روز هفته، تعطیلات ۱۴۰۵ و مسافت به زبان فارسی
        """
        try:
            origin = origin_city.strip() if origin_city and origin_city.strip() else self.valves.default_origin_city
            sh1, dt1 = self._parse_shamsi_date(start_shamsi_date)
            sh2, dt2 = self._parse_shamsi_date(end_shamsi_date)
            if dt2 < dt1:
                return json.dumps({"خطا": "تاریخ پایان نمی‌تواند قبل از تاریخ شروع باشد."}, ensure_ascii=False)

            all_days = []
            non_working_days = []
            cur = dt1
            while cur <= dt2:
                pair = self._greg_to_shamsi_info(cur)
                if pair:
                    sk, inf = pair
                    is_off = bool(inf[2])
                    is_fri = bool(inf[3])
                    if is_off and is_fri:
                        day_type = "تعطیل رسمی و جمعه"
                    elif is_off:
                        day_type = "تعطیل رسمی"
                    elif is_fri:
                        day_type = "جمعه"
                    else:
                        day_type = "روز کاری عادی"
                    item = {
                        "تاریخ_شمسی": sk,
                        "روز_هفته": inf[1],
                        "نوع_روز": day_type,
                        "مناسبت": inf[4] or "ندارد",
                    }
                    all_days.append(item)
                    if is_off or is_fri:
                        non_working_days.append({
                            **item,
                            "برچسب_نمایشی": self._format_holiday_label(sk, inf),
                        })
                cur += timedelta(days=1)

            dist_km = self._lookup_city_distance(origin, destination_city)
            res = {
                "شهر_مبدأ": origin,
                "شهر_مقصد": destination_city,
                "تاریخ_شروع": all_days[0] if all_days else None,
                "تاریخ_پایان": all_days[-1] if all_days else None,
                "تمام_روزهای_بازه": all_days,
                "روزهای_غیرکاری_بازه": non_working_days,
                "فاصله_یک_طرفه_کیلومتر": dist_km,
                "فاصله_رفت_و_برگشت_کیلومتر": dist_km * 2 if dist_km is not None else None,
                "مسافت_در_جدول_یافت_شد": dist_km is not None,
            }
            return json.dumps(res, ensure_ascii=False)
        except Exception as exc:
            return json.dumps({"خطا": str(exc)}, ensure_ascii=False)

    # =====================================================================
    # ابزار عمومی ۲: گام اول الزامی — بررسی کسری اطلاعات و صدور خلاصه تأیید
    # =====================================================================
    async def prepare_mission_confirmation(
        self,
        personnel_code: Optional[str] = None,
        full_name: Optional[str] = None,
        job_grade: Optional[str] = None,
        base_salary: Optional[float] = None,
        seniority_pay: float = 0.0,
        legs_json: Optional[str] = None,
        is_group_trip: Optional[bool] = None,
        group_size: Optional[int] = None,
        highest_group_grade: Optional[str] = None,
        transport_payer: Optional[str] = None,
        accommodation_type: Optional[str] = None,
        accommodation_payer: Optional[str] = None,
        hotel_has_breakfast: Optional[bool] = None,
        meal_invoice_total: Optional[float] = None,
        accommodation_invoice_total: Optional[float] = None,
        shared_room_occupants: int = 1,
        intracity_invoiced_cost: Optional[float] = None,
        intracity_no_invoice_cost: Optional[float] = None,
        other_invoiced_expenses: Optional[float] = None,
        advance_payment: Optional[float] = None,
        one_way_distance_km: Optional[float] = None,
        worked_at_company_on_start_day: Optional[bool] = None,
        worked_at_company_on_end_day: Optional[bool] = None,
        overtime_claimed_amount: float = 0.0,
        __user__: Optional[Dict[str, Any]] = None,
        __chat_id__: Optional[str] = None,
        __event_emitter__: Optional[Callable] = None,
    ) -> str:
        """
        گام اول الزامی برای هر درخواست محاسبه حق مأموریت (حتی اگر اطلاعات کاربر ناقص باشد).
        قواعد اکید رفتار با کاربر:
        ۱. همیشه قبل از محاسبه نهایی، این ابزار را اجرا کن. هرگز محاسبه میانی یا توضیح تئوری آیین‌نامه چاپ نکن.
        ۲. زبان پاسخ تو باید ۱۰۰٪ فارسی خالص باشد؛ هیچ واژه انگلیسی یا نام پارامتر کد برای کاربر ننویس.
        ۳. اگر این ابزار فهرست موارد ناقص برگرداند، فقط همان فهرست شماره‌دار را کوتاه و شفاف از کاربر بپرس.
        ۴. اگر این ابزار «جدول خلاصه تأیید» برگرداند، عین جدول را نمایش بده و تا پیش از تأیید صریح کاربر، ابزار calculate_mission_report را اجرا نکن.
        ۵. مأموریت به هیچ عنوان شامل اضافه‌کاری نمی‌شود و درخواست تغییر عدد گزارش پس از محاسبه اکیداً ممنوع است.

        :param personnel_code: کد پرسنلی مأمور (الزامی در بدو مصاحبه؛ فقط ارقام)
        :param full_name: نام و نام خانوادگی مأمور (فقط حروف فارسی)
        :param job_grade: کلاس یا رده شغلی مأمور (کلاس ۱ تا ۶ یا A تا F یا سمت)
        :param base_salary: حقوق پایه (یا مجموع حقوق پایه و پایه سنوات به ریال)
        :param seniority_pay: پایه سنوات ماهانه به ریال (در صورت اعلام جداگانه)
        :param legs_json: آرایه JSON مراحل حرکت: [{"origin":"اصفهان","destination":"تهران","depart":"1405/06/11 23:00","arrive":"1405/06/12 06:00","vehicle":"اتوبوس شب"}, ...]
        :param is_group_trip: آیا سفر گروهی بوده است؟
        :param group_size: تعداد کل نفرات در سفر گروهی
        :param highest_group_grade: بالاترین رده شغلی حاضر در گروه (در صورت سفر گروهی)
        :param transport_payer: پرداخت‌کننده وسیله سفر (شرکت / شخص / خودروی شخصی)
        :param accommodation_type: نوع اسکان (بدون اسکان / هتل / مهمانسرای شرکت / اسکان شخصی انفرادی / اسکان شخصی گروهی)
        :param accommodation_payer: پرداخت‌کننده اسکان (شرکت / شخص)
        :param hotel_has_breakfast: اگر اسکان هتل بوده، آیا صبحانه داشته است؟
        :param meal_invoice_total: مجموع فاکتور معتبر غذا به ریال (اگر نداشته ۰)
        :param accommodation_invoice_total: مبلغ فاکتور اسکان شخصی به ریال (اگر نداشته ۰)
        :param shared_room_occupants: تعداد نفرات شریک در اتاق مشترک
        :param intracity_invoiced_cost: هزینه تردد درون‌شهری با فاکتور (تاکسی و تاکسی اینترنتی) به ریال
        :param intracity_no_invoice_cost: هزینه تردد درون‌شهری بدون فاکتور به ریال
        :param other_invoiced_expenses: سایر هزینه‌های جانبی مجاز با فاکتور به ریال (بدون اضافه‌کاری)
        :param advance_payment: مبلغ علی‌الحساب پرداخت‌شده به ریال (اگر نداشته ۰)
        :param one_way_distance_km: فاصله یک‌طرفه کلیدی (فقط در صورت نبود شهر در جدول اصفهان)
        :param worked_at_company_on_start_day: آیا در روز شروع مأموریت در شرکت حاضر بوده است؟
        :param worked_at_company_on_end_day: آیا در روز بازگشت باید در شرکت حاضر شود یا حاضر بوده است؟
        :param overtime_claimed_amount: اگر کاربر درخواست اضافه‌کاری کرده باشد (همیشه صفر لحاظ می‌شود)
        :return: فهرست کوتاه موارد ناقص برای پرسش از کاربر یا جدول خلاصه کامل فارسی جهت اخذ تأیید
        """
        try:
            missing: List[str] = []
            p_code_clean = ""
            if not personnel_code or not str(personnel_code).strip():
                missing.append("کد پرسنلی")
            else:
                p_code_clean = self._sanitize_personnel_code(personnel_code)

            f_name_clean = ""
            if not full_name or not str(full_name).strip():
                missing.append("نام و نام خانوادگی")
            else:
                f_name_clean = self._sanitize_full_name(full_name)

            if not job_grade or not str(job_grade).strip():
                missing.append("کلاس یا رده شغلی (کلاس ۱ تا ۶ یا عنوان سمت)")
            else:
                self._normalize_grade(job_grade)

            bs = self._to_non_negative_float(base_salary, "حقوق پایه", -1.0) if base_salary is not None else -1.0
            sp = self._to_non_negative_float(seniority_pay, "پایه سنوات", 0.0)
            if bs <= 0 and sp <= 0:
                missing.append("مبلغ حقوق پایه و پایه سنوات (به ریال)")

            parsed_legs: List[Dict[str, Any]] = []
            if not legs_json or not str(legs_json).strip():
                missing.append("تاریخ و ساعت دقیق حرکت و رسیدن همه مراحل سفر (و وسیله نقلیه هر مرحله)")
            else:
                parsed_legs = self._parse_legs(legs_json)

            if is_group_trip is None:
                missing.append("نوع سفر (تکی یا گروهی؟ در صورت گروهی: تعداد نفرات و بالاترین رده شغلی حاضر در گروه)")
            elif is_group_trip:
                if not group_size or int(group_size) < 2:
                    missing.append("تعداد کل نفرات در سفر گروهی")
                if not highest_group_grade or not str(highest_group_grade).strip():
                    missing.append("بالاترین کلاس یا رده شغلی حاضر در گروه")
                else:
                    self._normalize_grade(highest_group_grade)

            if not transport_payer or not str(transport_payer).strip():
                missing.append("پرداخت‌کننده هزینه وسیله سفر (شرکت یا شخص)")
            else:
                self._normalize_transport_payer(transport_payer)

            acc_type_norm = ""
            if not accommodation_type or not str(accommodation_type).strip():
                missing.append("نوع محل اسکان (بدون اسکان، هتل، مهمانسرای شرکت، اسکان شخصی انفرادی یا گروهی) و پرداخت‌کننده آن")
            else:
                acc_type_norm = self._normalize_accommodation_type(accommodation_type)
                if acc_type_norm != "none" and (not accommodation_payer or not str(accommodation_payer).strip()):
                    missing.append("پرداخت‌کننده هزینه اسکان (شرکت یا شخص)")
                if acc_type_norm == "hotel" and hotel_has_breakfast is None:
                    missing.append("وضعیت صبحانه هتل (آیا اسکان هتل شامل صبحانه بوده است یا خیر؟)")
                if acc_type_norm in ("personal_individual", "personal_group") and accommodation_payer and self._normalize_accommodation_payer(accommodation_payer) == "personal":
                    if accommodation_invoice_total is None:
                        missing.append("مبلغ فاکتور اسکان شخصی (به ریال)")

            if meal_invoice_total is None:
                missing.append("مجموع مبلغ فاکتورهای معتبر غذا در کل سفر (در صورت نداشتن فاکتور: صفر)")
            if intracity_invoiced_cost is None and intracity_no_invoice_cost is None:
                missing.append("هزینه ایاب‌وذهاب درون‌شهری شامل تاکسی و تاکسی اینترنتی (با تفکیک با فاکتور و بدون فاکتور؛ در صورت نبود: صفر)")
            if advance_payment is None:
                missing.append("مبلغ علی‌الحساب پرداخت‌شده (در صورت دریافت نکردن: صفر)")

            if parsed_legs:
                known_dists = [lg["distance_km"] for lg in parsed_legs if lg["distance_km"] is not None]
                if one_way_distance_km is None and not known_dists:
                    missing.append(
                        f"فاصله یک‌طرفه واقعی مسیر ({parsed_legs[0]['origin']} تا {parsed_legs[0]['destination']}) به کیلومتر"
                    )

            overtime_note = ""
            if self._to_non_negative_float(overtime_claimed_amount, "اضافه‌کاری", 0.0) > 0:
                overtime_note = "\n\n**تذکر مهم:** مطابق ضوابط شرکت، مأموریت به هیچ عنوان شامل اضافه‌کاری نمی‌شود و مبلغ اضافه‌کاری صفر لحاظ خواهد شد."

            if missing:
                q_lines = ["برای تکمیل و صدور گزارش حق مأموریت، لطفاً موارد زیر را اعلام فرمایید:"]
                for i, item in enumerate(missing, 1):
                    q_lines.append(f"{i}. {item}")
                if overtime_note:
                    q_lines.append(overtime_note.strip())
                q_lines.append("\n[دستورالعمل سیستم: فقط همین فهرست کوتاه را به فارسی خالص از کاربر بپرس و هیچ محاسبه میانی یا توضیح اضافه ننویس.]")
                return "\n".join(q_lines)

            # ذخیره قفل تأیید سمت سرور در SQLite برای این گفتگو
            user_info = self._extract_user_info(__user__)
            if __chat_id__:
                p_hash = hashlib.sha256(f"{p_code_clean}|{bs + sp}|{legs_json}".encode("utf-8")).hexdigest()[:16]
                self._save_confirmation_state(str(__chat_id__), user_info["id"], p_hash)

            grade_own = self._normalize_grade(job_grade or "")
            if is_group_trip and highest_group_grade:
                gg = self._normalize_grade(highest_group_grade)
                eff_grade = gg if GRADE_ORDER[gg] < GRADE_ORDER[grade_own] else grade_own
            else:
                eff_grade = grade_own

            tp_norm = self._normalize_transport_payer(transport_payer or "company")
            ap_norm = "company" if acc_type_norm == "none" else self._normalize_accommodation_payer(accommodation_payer or "company")

            trip_start_dt = parsed_legs[0]["dep_dt"]
            trip_end_dt = parsed_legs[-1]["arr_dt"]
            eff_start, eff_end, office_summary, start_wd, end_wd = self._evaluate_office_overlap(
                trip_start_dt, trip_end_dt, worked_at_company_on_start_day, worked_at_company_on_end_day
            )

            eff_sec = max(0, int(round((eff_end - eff_start).total_seconds())))
            d_total_preview = max(1, (eff_sec + 86399) // 86400) if eff_sec > 0 else 0
            _, hols = self._compute_holidays(eff_start, eff_end, d_total_preview)

            presence_hours = 0.0
            dwell_nights = 0
            for i in range(len(parsed_legs) - 1):
                arr_i = parsed_legs[i]["arr_dt"]
                dep_next = parsed_legs[i + 1]["dep_dt"]
                dwell = (dep_next - arr_i).total_seconds() / 3600.0
                if dwell > 0:
                    presence_hours += dwell
                    dwell_nights += max(0, (dep_next.date() - arr_i.date()).days)

            official_dists = [lg["official_distance_km"] for lg in parsed_legs if lg["official_distance_km"] is not None]
            known_dists = [lg["distance_km"] for lg in parsed_legs if lg["distance_km"] is not None]
            if official_dists:
                ow_km = max(official_dists)
            elif one_way_distance_km is not None:
                ow_km = float(one_way_distance_km)
            else:
                ow_km = max(known_dists) if known_dists else 0.0

            route_nodes = [parsed_legs[0]["origin"]] + [lg["destination"] for lg in parsed_legs]
            acc_type_map = {
                "none": "بدون اسکان", "hotel": "هتل", "company_guesthouse": "مهمانسرای شرکت",
                "personal_individual": "اسکان شخصی انفرادی", "personal_group": "اسکان شخصی گروهی",
            }
            payer_map = {"company": "شرکت", "personal": "شخص", "personal_car": "شخص (خودروی شخصی)"}
            bf_text = "موضوعیت ندارد" if acc_type_norm != "hotel" else ("بله" if hotel_has_breakfast else "خیر")
            grade_text = GRADE_LABELS_FA[grade_own] if eff_grade == grade_own else f"{GRADE_LABELS_FA[grade_own]} (مؤثر گروه: {GRADE_LABELS_FA[eff_grade]})"
            trip_type_text = f"گروهی ({int(group_size or 2)} نفر)" if is_group_trip else "تکی (انفرادی)"

            summary_lines = [
                "### خلاصه اطلاعات مأموریت جهت تأیید نهایی",
                "",
                "| مشخصه | مقدار ثبت‌شده |",
                "|---|---|",
                f"| کد پرسنلی و نام | {p_code_clean} — {f_name_clean} |",
                f"| کلاس شغلی | {grade_text} |",
                f"| مبنای حقوق (پایه + سنوات) | {self._fmt_rial(bs + sp)} ریال |",
                f"| نوع سفر | {trip_type_text} |",
                f"| مسیر سفر (مبدأ پیش‌فرض: {self.valves.default_origin_city}) | {' ← '.join(route_nodes)} (فاصله یک‌طرفه: {ow_km:,.0f} کیلومتر) |",
                f"| حرکت از مبدأ | {start_wd} {parsed_legs[0]['depart']} |",
                f"| بازگشت به مبدأ | {end_wd} {parsed_legs[-1]['arrive']} |",
                f"| مدت حضور و شب اقامت واقعی در مقصد | {presence_hours:.2f} ساعت ({dwell_nights} شب) |",
                f"| تعطیلات و جمعه‌های تقویم ۱۴۰۵ در بازه | {'، '.join(hols) if hols else 'ندارد'} |",
                f"| وضعیت حضور در شرکت (بند ۵-۴-۱-۳) | {office_summary} |",
                f"| وسیله سفر و پرداخت‌کننده | {' / '.join(dict.fromkeys(lg['vehicle_label'] for lg in parsed_legs))} ({payer_map[tp_norm]}) |",
                f"| محل اسکان و پرداخت‌کننده | {acc_type_map[acc_type_norm]} ({payer_map[ap_norm]}) — صبحانه هتل: {bf_text} |",
                f"| فاکتور غذا / فاکتور اسکان | {self._fmt_rial(self._to_non_negative_float(meal_invoice_total, 'فاکتور غذا', 0.0))} / {self._fmt_rial(self._to_non_negative_float(accommodation_invoice_total, 'فاکتور اسکان', 0.0))} ریال |",
                f"| تردد درون‌شهری (با فاکتور / بدون فاکتور) | {self._fmt_rial(self._to_non_negative_float(intracity_invoiced_cost, 'تردد با فاکتور', 0.0))} / {self._fmt_rial(self._to_non_negative_float(intracity_no_invoice_cost, 'تردد بدون فاکتور', 0.0))} ریال |",
                f"| سایر هزینه‌های مجاز / علی‌الحساب | {self._fmt_rial(self._to_non_negative_float(other_invoiced_expenses, 'سایر هزینه‌ها', 0.0))} / {self._fmt_rial(self._to_non_negative_float(advance_payment, 'علی‌الحساب', 0.0))} ریال |",
            ]
            if overtime_note:
                summary_lines.append(overtime_note)
            summary_lines.append("")
            summary_lines.append("لطفاً اطلاعات بالا را بررسی و در صورت صحت، تأیید فرمایید تا محاسبه نهایی انجام شود.")
            summary_lines.append("\n[دستورالعمل سیستم: عین جدول خلاصه و جمله تأیید بالا را بدون عدد محاسباتی و بدون هیچ واژه انگلیسی نمایش بده و تا پیش از تأیید صریح کاربر، ابزار محاسبه نهایی را اجرا نکن.]")
            return "\n".join(summary_lines)
        except Exception as exc:
            return f"خطا در بررسی اطلاعات مأموریت: {exc}"

    # =====================================================================
    # ابزار عمومی ۳: گام دوم الزامی — محاسبه قطعی و صدور فرم با کد یکتا
    # =====================================================================
    async def calculate_mission_report(
        self,
        personnel_code: str,
        full_name: str,
        job_grade: str,
        base_salary: float,
        seniority_pay: float,
        legs_json: str,
        user_confirmed: bool = False,
        is_group_trip: bool = False,
        group_size: int = 1,
        highest_group_grade: str = "",
        transport_payer: str = "company",
        accommodation_type: str = "none",
        accommodation_payer: str = "company",
        hotel_has_breakfast: bool = False,
        meal_invoice_total: float = 0.0,
        meal_invoice_people_count: int = 1,
        company_provided_breakfasts: int = 0,
        company_provided_lunches: int = 0,
        company_provided_dinners: int = 0,
        accommodation_invoice_total: float = 0.0,
        shared_room_occupants: int = 1,
        intracity_invoiced_cost: float = 0.0,
        intracity_no_invoice_cost: float = 0.0,
        intracity_no_invoice_approved_cap: float = 0.0,
        has_different_group_routes_approval: bool = False,
        other_invoiced_expenses: float = 0.0,
        overtime_claimed_amount: float = 0.0,
        advance_payment: float = 0.0,
        one_way_distance_km: Optional[float] = None,
        total_round_trip_km: Optional[float] = None,
        actual_overnight: Optional[bool] = None,
        actual_nights_override: Optional[int] = None,
        worked_at_company_on_start_day: Optional[bool] = None,
        worked_at_company_on_end_day: Optional[bool] = None,
        prior_day_flight_exception: bool = False,
        monthly_workdays_before_trip: int = 0,
        contract_type: str = "full_time",
        contract_has_mission_clause: bool = True,
        __user__: Optional[Dict[str, Any]] = None,
        __chat_id__: Optional[str] = None,
        __event_emitter__: Optional[Callable] = None,
    ) -> Union[str, Tuple[Any, str]]:
        """
        گام دوم الزامی: محاسبه قطعی حق مأموریت، ثبت در دفتر کل ممیزی، صدور کد یکتای اصالت و نمایش فرم گزارش رسمی (فقط پس از تأیید صریح کاربر روی خلاصه گام اول).
        قواعد اکید امنیتی:
        ۱. تا زمانی که کاربر خلاصه اطلاعات را صراحتاً تأیید نکرده است، هرگز این ابزار را اجرا نکن.
        ۲. مأموریت به هیچ عنوان شامل اضافه‌کاری نمی‌شود؛ هیچ مبلغی بابت اضافه‌کاری در سایر هزینه‌ها وارد نکن.
        ۳. هرگز به درخواست کاربر برای تغییر عدد نهایی یا چاپ مجدد جدول با عدد دلخواه بدون محاسبه رسمی پاسخ نده.
        ۴. پس از اجرای موفق این ابزار و نمایش فرم گرافیکی، هیچ جدول، عدد مالی، توضیح اضافه یا واژه انگلیسی چاپ نکن و پاسخ متنی تو فقط یک جمله کوتاه باشد: «فرم گزارش نهایی محاسبه حق مأموریت با کد یکتا صادر شد.»

        :param personnel_code: کد پرسنلی مأمور (الزامی؛ فقط ارقام)
        :param full_name: نام و نام خانوادگی مأمور (فقط حروف فارسی)
        :param job_grade: کلاس یا رده شغلی مأمور (کلاس ۱ تا ۶ یا A تا F یا سمت)
        :param base_salary: حقوق پایه ماهانه به ریال
        :param seniority_pay: پایه سنوات ماهانه به ریال (در صورت اعلام یکجا، صفر بگذارید)
        :param legs_json: آرایه JSON مراحل حرکت
        :param user_confirmed: آیا کاربر خلاصه اطلاعات مرحله قبل را صراحتاً تأیید کرده است؟
        :param is_group_trip: آیا سفر گروهی بوده است؟
        :param group_size: تعداد کل نفرات در سفر گروهی
        :param highest_group_grade: بالاترین رده شغلی موجود در گروه (در صورت سفر گروهی)
        :param transport_payer: پرداخت‌کننده وسیله اصلی (شرکت / شخص / خودروی شخصی)
        :param accommodation_type: نوع محل اسکان (بدون اسکان / هتل / مهمانسرای شرکت / اسکان شخصی انفرادی / اسکان شخصی گروهی)
        :param accommodation_payer: پرداخت‌کننده اسکان (شرکت / شخص)
        :param hotel_has_breakfast: اگر اسکان هتل بوده، آیا صبحانه داشته است؟
        :param meal_invoice_total: مجموع مبلغ فاکتورهای معتبر غذای مأمور در کل سفر (ریال)
        :param meal_invoice_people_count: تعداد افرادی که فاکتور غذا برای آن‌ها بوده است (پیش‌فرض ۱)
        :param company_provided_breakfasts: تعداد صبحانه‌های تأمین‌شده توسط شرکت
        :param company_provided_lunches: تعداد ناهارهای تأمین‌شده توسط شرکت
        :param company_provided_dinners: تعداد شام‌های تأمین‌شده توسط شرکت
        :param accommodation_invoice_total: مبلغ فاکتور اسکان شخصی (ریال)
        :param shared_room_occupants: تعداد نفرات شریک در اتاق مشترک
        :param intracity_invoiced_cost: هزینه تردد درون‌شهری با فاکتور به ریال
        :param intracity_no_invoice_cost: هزینه تردد درون‌شهری بدون فاکتور به ریال
        :param intracity_no_invoice_approved_cap: سقف مصوب هزینه درون‌شهری بدون فاکتور
        :param has_different_group_routes_approval: تأیید مدیر برای مسیرهای متفاوت درون‌شهری در سفر گروهی
        :param other_invoiced_expenses: سایر هزینه‌های جانبی مجاز با فاکتور (به‌جز اضافه‌کاری)
        :param overtime_claimed_amount: مبلغ ادعایی اضافه‌کاری (همواره صفر محاسبه و هشدار ثبت می‌شود)
        :param advance_payment: مبلغ علی‌الحساب پرداخت‌شده به مأمور (ریال)
        :param one_way_distance_km: فاصله یک‌طرفه کلیدی (فقط برای شهرهای خارج از جدول رسمی)
        :param total_round_trip_km: مجموع کیلومتر رفت‌وبرگشت واقعی (اختیاری)
        :param actual_overnight: آیا شب‌مانی واقعی در مقصد انجام شده است؟
        :param actual_nights_override: تعداد شب اقامت واقعی دستی در مقصد (در صورت استفاده هشدار ممیزی ثبت می‌شود)
        :param worked_at_company_on_start_day: حضور در شرکت در روز شروع مأموریت (بند ۵-۴-۱-۳)
        :param worked_at_company_on_end_day: حضور در شرکت در روز بازگشت (بند ۵-۴-۱-۳)
        :param prior_day_flight_exception: استثنای بلیت هواپیمای روز قبل برای اسکان
        :param monthly_workdays_before_trip: تعداد روزهای کاری مأموریت قبلی فرد در همین ماه شمسی
        :param contract_type: نوع قرارداد (تمام‌وقت / نیمه‌وقت / پروژه‌ای / دائم‌المأمور)
        :param contract_has_mission_clause: برای نیمه‌وقت یا پروژه‌ای، آیا در قرارداد حق مأموریت تصریح شده است؟
        :return: فرم گزارش گرافیکی با کد یکتا و پیام کوتاه بدون تکرار به مدل، یا جدول گزارش فارسی
        """
        try:
            if not user_confirmed:
                return (
                    "محاسبه نهایی متوقف شد؛ زیرا هنوز تأیید صریح کاربر روی خلاصه ورودی‌ها دریافت نشده است. "
                    "ابتدا ابزار prepare_mission_confirmation را اجرا کن، جدول خلاصه را به زبان فارسی خالص برای کاربر نمایش بده "
                    "و فقط پس از تأیید صریح کاربر، این ابزار را مجدداً با user_confirmed=True فراخوانی کن."
                )

            if self.valves.enforce_server_confirmation_lock and __chat_id__:
                if not self._has_confirmation_state(str(__chat_id__)):
                    return (
                        "محاسبه نهایی متوقف شد؛ زیرا هنوز مرحله صدور جدول خلاصه و اخذ تأیید (prepare_mission_confirmation) "
                        "در این گفتگو انجام نشده است. ابتدا خلاصه اطلاعات را به کاربر نمایش بده و پس از تأیید او محاسبه را اجرا کن."
                    )

            if __event_emitter__:
                await __event_emitter__({
                    "type": "status",
                    "data": {"description": "در حال اعتبارسنجی، محاسبه و صدور کد یکتای مأموریت...", "done": False},
                })

            p_code = self._sanitize_personnel_code(personnel_code)
            f_name = self._sanitize_full_name(full_name)

            bs = self._to_non_negative_float(base_salary, "حقوق پایه")
            sp = self._to_non_negative_float(seniority_pay, "پایه سنوات")
            if (bs + sp) <= 0:
                raise ValueError("مجموع حقوق پایه و پایه سنوات باید بزرگ‌تر از صفر باشد.")

            grade_own = self._normalize_grade(job_grade)
            if is_group_trip and highest_group_grade and highest_group_grade.strip():
                grade_group = self._normalize_grade(highest_group_grade)
                effective_grade = grade_group if GRADE_ORDER[grade_group] < GRADE_ORDER[grade_own] else grade_own
            else:
                effective_grade = grade_own

            tp_norm = self._normalize_transport_payer(transport_payer)
            acc_type_norm = self._normalize_accommodation_type(accommodation_type)
            acc_payer_norm = "company" if acc_type_norm == "none" else self._normalize_accommodation_payer(accommodation_payer)
            contract_norm = self._normalize_contract_type(contract_type)

            meals_rates = json.loads(self.valves.rates_meals_accommodation_json)
            advance_rates = json.loads(self.valves.advance_ceilings_json)
            if effective_grade not in meals_rates or effective_grade not in advance_rates:
                raise ValueError("نرخ غذا، اسکان یا علی‌الحساب برای رده شغلی انتخاب‌شده یافت نشد.")

            grade_rate = meals_rates[effective_grade]
            adv_rate = advance_rates[effective_grade]

            salary_base = bs + sp
            daily_rate = salary_base / float(self.valves.daily_denominator)
            hourly_rate = salary_base / float(self.valves.hourly_denominator)

            parsed_legs = self._parse_legs(legs_json)
            trip_start_dt = parsed_legs[0]["dep_dt"]
            trip_end_dt = parsed_legs[-1]["arr_dt"]
            total_trip_hours = (trip_end_dt - trip_start_dt).total_seconds() / 3600.0
            if total_trip_hours <= 0:
                raise ValueError("مدت کل سفر باید بزرگ‌تر از صفر باشد.")

            presence_hours = 0.0
            dwell_nights = 0
            for i in range(len(parsed_legs) - 1):
                arr_i = parsed_legs[i]["arr_dt"]
                dep_next = parsed_legs[i + 1]["dep_dt"]
                dwell = (dep_next - arr_i).total_seconds() / 3600.0
                if dwell > 0:
                    presence_hours += dwell
                    dwell_nights += max(0, (dep_next.date() - arr_i.date()).days)

            presence_days = presence_hours / 24.0
            warnings: List[str] = []

            if actual_nights_override is not None:
                nights = self._to_non_negative_int(actual_nights_override, "تعداد شب اقامت")
                if nights != dwell_nights:
                    warnings.append(
                        f"تعداد شب اقامت به‌صورت دستی ({nights} شب به‌جای {dwell_nights} شب محاسبه‌شده) ثبت شده و نیازمند بررسی مستندات در امور مالی است."
                    )
            else:
                nights = dwell_nights

            is_overnight = actual_overnight if actual_overnight is not None else (nights >= 1)

            # قفل جدول رسمی مسافت‌ها (جلوگیری از دستکاری مسافت شهرهای شناخته‌شده)
            official_dists = [lg["official_distance_km"] for lg in parsed_legs if lg["official_distance_km"] is not None]
            known_dists = [lg["distance_km"] for lg in parsed_legs if lg["distance_km"] is not None]
            if official_dists:
                ow_km = max(official_dists)
                if one_way_distance_km is not None:
                    req_km = self._to_non_negative_float(one_way_distance_km, "فاصله یک‌طرفه")
                    if abs(req_km - ow_km) > 1.0:
                        warnings.append(
                            f"فاصله یک‌طرفه اعلام‌شده ({req_km:,.0f} کیلومتر) با جدول رسمی ({ow_km:,.0f} کیلومتر) مغایرت داشت؛ عدد جدول رسمی ملاک محاسبه قرار گرفت."
                        )
            elif one_way_distance_km is not None:
                ow_km = self._to_non_negative_float(one_way_distance_km, "فاصله یک‌طرفه")
            elif known_dists:
                ow_km = max(known_dists)
            else:
                raise ValueError(
                    f"فاصله یک‌طرفه مسیر ({parsed_legs[0]['origin']} تا {parsed_legs[0]['destination']}) در جدول مسافت‌ها یافت نشد؛ لطفاً فاصله واقعی به کیلومتر را اعلام فرمایید."
                )

            if len(parsed_legs) > 2:
                if all(lg["distance_km"] is not None for lg in parsed_legs):
                    rt_km = sum(float(lg["distance_km"]) for lg in parsed_legs)
                elif total_round_trip_km is not None:
                    rt_km = self._to_non_negative_float(total_round_trip_km, "مجموع کیلومتر رفت‌وبرگشت")
                elif tp_norm == "personal_car" and not is_group_trip:
                    raise ValueError("برای محاسبه هزینه کیلومتری خودروی شخصی در سفر چندمرحله‌ای، مسافت تمام مراحل یا مجموع کیلومتر کل سفر الزامی است.")
                else:
                    rt_km = ow_km * 2.0
            else:
                rt_km = ow_km * 2.0

            # قانون مطلق: مأموریت به هیچ عنوان شامل اضافه‌کاری نمی‌شود
            ot_claimed = self._to_non_negative_float(overtime_claimed_amount, "مبلغ اضافه‌کاری", 0.0)
            if ot_claimed > 0:
                warnings.append("مطابق ضوابط شرکت، مأموریت به هیچ عنوان شامل اضافه‌کاری نمی‌شود؛ مبلغ اضافه‌کاری صفر لحاظ شد.")

            mission_pay_eligible = True
            if contract_norm == "permanent_mission":
                mission_pay_eligible = False
                warnings.append("شغل دائم‌المأمور مشمول فوق‌العاده حق مأموریت این آیین‌نامه نیست.")
            elif contract_norm in ("part_time", "project") and not contract_has_mission_clause:
                mission_pay_eligible = False
                warnings.append("برای پرسنل نیمه‌وقت یا پروژه‌ای بدون تصریح قراردادی، فوق‌العاده حق مأموریت تعلق نمی‌گیرد.")
            elif ow_km < self.valves.min_distance_km and not is_overnight:
                mission_pay_eligible = False
                warnings.append(
                    f"فاصله یک‌طرفه ({ow_km:,.0f} کیلومتر) کمتر از {self.valves.min_distance_km:.0f} کیلومتر است و شب‌مانی واقعی در مقصد ثبت نشده؛ فوق‌العاده برون‌شهری تعلق نمی‌گیرد."
                )

            daily_eff_start, daily_eff_end, office_overlap_summary, start_wd, end_wd = self._evaluate_office_overlap(
                trip_start_dt, trip_end_dt, worked_at_company_on_start_day, worked_at_company_on_end_day
            )

            eff_daily_sec = max(0, int(round((daily_eff_end - daily_eff_start).total_seconds())))
            if eff_daily_sec > 0:
                d_total = max(1, (eff_daily_sec + 86399) // 86400)
                d_holiday, holidays_list = self._compute_holidays(daily_eff_start, daily_eff_end, d_total)
                d_normal = max(0.0, float(d_total) - d_holiday)
            else:
                d_total = 0
                d_holiday = 0.0
                d_normal = 0.0
                holidays_list = []

            if mission_pay_eligible and d_total > 0:
                daily_mission_pay = self._round_half_up(
                    daily_rate * (d_normal + self.valves.holiday_multiplier * d_holiday)
                )
            else:
                daily_mission_pay = 0

            legs_detail = []
            if not mission_pay_eligible:
                route_pay = 0
                for lg in parsed_legs:
                    legs_detail.append({**lg, "leg_pay": 0})
            elif len(parsed_legs) == 2 and parsed_legs[0]["origin"] == parsed_legs[1]["destination"]:
                out_lg, ret_lg = parsed_legs[0], parsed_legs[1]
                h_out, wh_out = out_lg["hours"], out_lg["weighted_hours"]
                h_ret, wh_ret = ret_lg["hours"], ret_lg["weighted_hours"]
                f_coef = (wh_out / h_out) if h_out > 0 else 1.0
                e_coef = (wh_ret / h_ret) if h_ret > 0 else 1.0
                c_total = h_out + h_ret
                d_pair = self._get_pair_coefficient(out_lg["vehicle_code"], ret_lg["vehicle_code"])
                route_pay = self._round_half_up(hourly_rate * c_total * f_coef * e_coef * d_pair) if c_total > 0 else 0
                out_share = self._round_half_up(route_pay * (h_out / c_total)) if c_total > 0 else 0
                ret_share = route_pay - out_share
                legs_detail.append({**out_lg, "leg_pay": out_share})
                legs_detail.append({**ret_lg, "leg_pay": ret_share})
            else:
                route_pay = 0
                for lg in parsed_legs:
                    hk, whk = lg["hours"], lg["weighted_hours"]
                    fk = (whk / hk) if hk > 0 else 1.0
                    dk = SINGLE_VEHICLE_COEFFICIENTS[lg["vehicle_code"]]
                    leg_p = self._round_half_up(hourly_rate * hk * fk * 1.0 * dk) if hk > 0 else 0
                    route_pay += leg_p
                    legs_detail.append({**lg, "leg_pay": leg_p})

            total_payment = daily_mission_pay + route_pay

            acc_nights = nights if nights > 0 else (1 if prior_day_flight_exception else 0)
            if prior_day_flight_exception:
                warnings.append("استثنای بلیت هواپیمای روز قبل اعمال شده و نیازمند ارائه بلیت و تأیید در امور مالی است.")

            raw_meals = self._count_eligible_meals(trip_start_dt, trip_end_dt)
            hotel_bf_deduction = acc_nights if (acc_type_norm == "hotel" and hotel_has_breakfast) else 0
            eff_meals = {
                "breakfast": max(0, raw_meals["breakfast"] - self._to_non_negative_int(company_provided_breakfasts, "صبحانه شرکتی") - hotel_bf_deduction),
                "lunch": max(0, raw_meals["lunch"] - self._to_non_negative_int(company_provided_lunches, "ناهار شرکتی")),
                "dinner": max(0, raw_meals["dinner"] - self._to_non_negative_int(company_provided_dinners, "شام شرکتی")),
            }
            meal_cap_total = (
                eff_meals["breakfast"] * grade_rate["breakfast"]
                + eff_meals["lunch"] * grade_rate["lunch"]
                + eff_meals["dinner"] * grade_rate["dinner"]
            )
            meal_inv_raw = self._to_non_negative_float(meal_invoice_total, "فاکتور غذا")
            meal_people = max(1, self._to_non_negative_int(meal_invoice_people_count, "تعداد افراد فاکتور غذا", 1))
            meal_inv_share = meal_inv_raw / meal_people
            meal_payable = self._round_half_up(min(meal_inv_share, float(meal_cap_total))) if meal_inv_share > 0 else 0

            acc_inv = self._to_non_negative_float(accommodation_invoice_total, "فاکتور اسکان")
            if acc_type_norm in ("none", "company_guesthouse") or acc_payer_norm == "company":
                accommodation_payable = 0
                if acc_inv > 0:
                    warnings.append("به دلیل نبود اسکان یا تأمین اسکان توسط شرکت، هزینه اسکان نقدی قابل پرداخت صفر لحاظ شد.")
            elif nights == 0 and ow_km <= self.valves.one_day_no_accommodation_max_km and not prior_day_flight_exception:
                accommodation_payable = 0
                if acc_inv > 0:
                    warnings.append(
                        f"در مأموریت بدون شب‌مانی واقعی تا {self.valves.one_day_no_accommodation_max_km:.0f} کیلومتر (بدون استثنای پرواز روز قبل) هزینه اسکان تعلق نمی‌گیرد."
                    )
            else:
                if acc_inv <= 0 or acc_nights <= 0:
                    accommodation_payable = 0
                elif is_group_trip or acc_type_norm == "personal_group":
                    occ = max(1, self._to_non_negative_int(shared_room_occupants, "تعداد نفرات اتاق مشترک", 1))
                    per_person_inv = acc_inv / occ
                    acc_cap = acc_nights * float(grade_rate["accommodation"])
                    accommodation_payable = self._round_half_up(min(per_person_inv, acc_cap))
                else:
                    acc_cap = acc_nights * 0.50 * float(grade_rate["accommodation"])
                    accommodation_payable = self._round_half_up(min(acc_inv, acc_cap))

            mileage_pay = 0
            if tp_norm == "personal_car":
                if is_group_trip:
                    warnings.append("استفاده از خودروی شخصی در سفرهای گروهی مجاز نیست؛ هزینه کیلومتری صفر محاسبه شد.")
                else:
                    mileage_pay = self._round_half_up(rt_km * self.valves.rate_per_km_rials)

            intracity_invoiced = self._to_non_negative_float(intracity_invoiced_cost, "تردد درون‌شهری با فاکتور")
            intracity_no_inv = self._to_non_negative_float(intracity_no_invoice_cost, "تردد درون‌شهری بدون فاکتور")
            intracity_cap_no_inv = self._to_non_negative_float(intracity_no_invoice_approved_cap, "سقف مصوب تردد بدون فاکتور")
            intracity_claimed_total = self._round_half_up(intracity_invoiced + intracity_no_inv)

            has_company_car = any(lg["is_company_car"] for lg in parsed_legs)
            visited_cities = [lg["destination"] for lg in parsed_legs]
            is_tehran_dest = any("تهران" in c for c in visited_cities)

            if intracity_claimed_total > 0 and (tp_norm == "personal_car" or has_company_car) and (not is_tehran_dest):
                if is_group_trip and has_different_group_routes_approval and intracity_invoiced > 0:
                    intracity_payable = self._round_half_up(intracity_invoiced)
                    warnings.append("پرداخت تردد درون‌شهری گروهی با مسیرهای متفاوت منوط به ارائه فاکتور و تأیید مدیر واحد در امور مالی است.")
                    if intracity_no_inv > 0:
                        warnings.append("در سفر گروهی با مسیرهای متفاوت درون‌شهری، صرفاً هزینه دارای فاکتور و تأیید مدیر قابل پرداخت است.")
                else:
                    intracity_payable = 0
                    warnings.append(
                        "مطابق تبصره ۵ آیین‌نامه، در صورت استفاده از خودروی شخصی یا خودروی شرکت (به‌جز کلان‌شهر تهران به‌دلیل طرح ترافیک)، هزینه تاکسی درون‌شهری پرداخت نمی‌شود."
                    )
            else:
                if intracity_no_inv > 0 and intracity_cap_no_inv > 0 and intracity_no_inv > intracity_cap_no_inv:
                    warnings.append(
                        f"هزینه تردد درون‌شهری بدون فاکتور ({self._fmt_rial(intracity_no_inv)} ریال) از سقف مصوب ({self._fmt_rial(intracity_cap_no_inv)} ریال) بیشتر است (صرفاً هشدار؛ پرداختی مسدود نشد)."
                    )
                intracity_payable = intracity_claimed_total

            transport_payable = mileage_pay + intracity_payable
            other_payable = self._round_half_up(self._to_non_negative_float(other_invoiced_expenses, "سایر هزینه‌های مجاز"))
            if other_payable > 0:
                warnings.append(
                    f"مبلغ سایر هزینه‌های جانبی ({self._fmt_rial(other_payable)} ریال) نیازمند ارائه فاکتور معتبر، شرح مصوب و تأیید مدیر واحد و امور مالی است (اضافه‌کاری مجاز نیست)."
                )

            total_funds = meal_payable + accommodation_payable + transport_payable + other_payable
            gross_payable = total_payment + total_funds
            adv_paid = self._round_half_up(self._to_non_negative_float(advance_payment, "علی‌الحساب"))
            net_balance = gross_payable - adv_paid

            adv_daily_cap = (
                adv_rate["without_accommodation"]
                if (acc_payer_norm == "company" or acc_type_norm in ("none", "company_guesthouse"))
                else adv_rate["with_accommodation"]
            )
            adv_ceiling_total = adv_daily_cap * max(1, d_total)
            if adv_paid > adv_ceiling_total:
                warnings.append(
                    f"علی‌الحساب پرداخت‌شده ({self._fmt_rial(adv_paid)} ریال) از سقف جدول علی‌الحساب ({self._fmt_rial(adv_ceiling_total)} ریال) بیشتر است."
                )

            prev_wd = self._to_non_negative_int(monthly_workdays_before_trip, "روزهای کاری مأموریت قبلی در ماه")
            if prev_wd + d_normal > self.valves.monthly_workday_warning_limit:
                warnings.append(
                    f"مجموع روزهای کاری مأموریت ماهانه ({prev_wd + d_normal:.1f} روز) از سقف {self.valves.monthly_workday_warning_limit} روز کاری عبور کرده است."
                )

            route_nodes = [parsed_legs[0]["origin"]] + [lg["destination"] for lg in parsed_legs]
            route_chain = " ← ".join(route_nodes)
            own_lbl = GRADE_LABELS_FA[grade_own]
            eff_lbl = GRADE_LABELS_FA[effective_grade]
            grade_display = own_lbl if effective_grade == grade_own else f"{own_lbl} (مؤثر گروه: {eff_lbl})"
            trip_group_label = f"گروهی ({max(2, self._to_non_negative_int(group_size, 'تعداد نفرات گروه', 2))} نفر)" if is_group_trip else "تکی (انفرادی)"

            acc_type_map = {
                "none": "بدون اسکان",
                "hotel": "هتل",
                "company_guesthouse": "مهمانسرای شرکت",
                "personal_individual": "اسکان شخصی انفرادی",
                "personal_group": "اسکان شخصی گروهی",
            }
            payer_map = {
                "company": "شرکت",
                "personal": "شخص",
                "personal_car": "شخص (خودروی شخصی)",
            }
            if acc_type_norm == "hotel":
                hotel_bf_label = "بله (صبحانه هتل داشته است)" if hotel_has_breakfast else "خیر (بدون صبحانه)"
            else:
                hotel_bf_label = "موضوعیت ندارد (اسکان غیرهتلی)"

            veh_unique = list(dict.fromkeys(lg["vehicle_label"] for lg in parsed_legs))
            user_info = self._extract_user_info(__user__)
            registrant_display = (
                f"{user_info['name']} ({user_info['email']})"
                if user_info["email"] != "نامشخص"
                else user_info["name"]
            )

            report_data = {
                "mission_code": "",
                "registrant_display": registrant_display,
                "personnel_code": p_code,
                "full_name": f_name,
                "grade_display": grade_display,
                "trip_group_label": trip_group_label,
                "route_chain": route_chain,
                "one_way_km": ow_km,
                "round_trip_km": rt_km,
                "salary_base": salary_base,
                "daily_rate": daily_rate,
                "hourly_rate": hourly_rate,
                "origin_departure_display": f"{start_wd} {parsed_legs[0]['depart']}" if start_wd else parsed_legs[0]["depart"],
                "origin_arrival_display": f"{end_wd} {parsed_legs[-1]['arrive']}" if end_wd else parsed_legs[-1]["arrive"],
                "presence_hours": presence_hours,
                "presence_days": presence_days,
                "nights": nights,
                "d_total": d_total,
                "d_normal": d_normal,
                "d_holiday": d_holiday,
                "holidays_text": "، ".join(holidays_list) if holidays_list else "ندارد",
                "office_overlap_summary": office_overlap_summary,
                "legs_detail": legs_detail,
                "vehicle_summary": " / ".join(veh_unique),
                "transport_payer_label": payer_map[tp_norm],
                "accommodation_type_label": acc_type_map[acc_type_norm],
                "accommodation_payer_label": payer_map[acc_payer_norm],
                "hotel_breakfast_label": hotel_bf_label,
                "meals": eff_meals,
                "meal_cap_total": meal_cap_total,
                "meal_invoice_total": meal_inv_share,
                "intracity_payable": intracity_payable,
                "intracity_claimed_total": intracity_claimed_total,
                "daily_mission_pay": daily_mission_pay,
                "route_pay": route_pay,
                "total_payment": total_payment,
                "meal_payable": meal_payable,
                "accommodation_payable": accommodation_payable,
                "transport_payable": transport_payable,
                "other_expenses_payable": other_payable,
                "total_funds": total_funds,
                "gross_payable": gross_payable,
                "advance_payment": adv_paid,
                "net_balance": net_balance,
                "warnings": warnings,
            }

            # ثبت قطعی در دفتر کل ممیزی و دریافت کد یکتا
            mission_code = self._record_mission_ledger(user_info, report_data)
            report_data["mission_code"] = mission_code
            if __chat_id__:
                self._clear_confirmation_state(str(__chat_id__))

            if __event_emitter__:
                await __event_emitter__({
                    "type": "status",
                    "data": {"description": f"فرم گزارش حق مأموریت با کد یکتای {mission_code} صادر شد.", "done": True},
                })

            if self.valves.render_rich_html_form and HTMLResponse is not None:
                html_doc = self._build_rich_html_report(report_data)
                short_llm_signal = (
                    f"فرم گزارش گرافیکی نهایی محاسبه حق مأموریت با کد یکتای {mission_code} با موفقیت صادر و مستقیماً برای کاربر نمایش داده شده است. "
                    "هیچ جدول، عدد مالی، خلاصه یا توضیح اضافه‌ای تکرار نکن و فقط همین یک خط را به فارسی خالص پاسخ بده: "
                    f"«فرم گزارش نهایی محاسبه حق مأموریت با کد یکتای {mission_code} صادر شد.»"
                )
                return (
                    HTMLResponse(content=html_doc, headers={"Content-Disposition": "inline"}),
                    short_llm_signal,
                )

            return self._build_markdown_report(report_data)

        except Exception as exc:
            if __event_emitter__:
                await __event_emitter__({
                    "type": "status",
                    "data": {"description": f"خطا در محاسبه: {exc}", "done": True},
                })
            return f"خطا در محاسبه مأموریت: {exc}"

    # =====================================================================
    # ابزار عمومی ۴: راستی‌آزمایی کد یکتای مأموریت (ویژه امور مالی و منابع انسانی)
    # =====================================================================
    async def verify_mission_code(
        self,
        mission_code: str,
        __user__: Optional[Dict[str, Any]] = None,
        __event_emitter__: Optional[Callable] = None,
    ) -> str:
        """
        راستی‌آزمایی اصالت کد یکتای مأموریت (مانند MS-1405-0001-8F3A) در دفتر کل سرور جهت جلوگیری از جعل اعداد فرم چاپی.
        فقط مدیر سیستم، ایمیل‌های مجاز ثبت‌شده در Valves (مالی و منابع انسانی) یا خود ثبت‌کننده اصلی گزارش مجاز به مشاهده جزئیات هستند.

        :param mission_code: کد یکتای درج‌شده در بالای فرم گزارش مأموریت
        :return: نتیجه بررسی اصالت و ارقام اصلی ثبت‌شده در سرور به زبان فارسی
        """
        try:
            code = self._norm_digits(mission_code).upper().strip()
            if not re.fullmatch(r"MS-\d{4}-\d{4,}-[0-9A-F]{4}", code):
                return "قالب کد یکتای واردشده معتبر نیست. نمونه صحیح: MS-1405-0001-8F3A"

            user_info = self._extract_user_info(__user__)
            allowed_emails = {
                em.strip().lower()
                for em in (self.valves.auditor_emails or "").split(",")
                if em.strip()
            }
            is_auditor = (user_info["role"] == "admin") or (user_info["email"].lower() in allowed_emails)

            conn = self._init_ledger_db()
            try:
                row = conn.execute(
                    """
                    SELECT seq_id, mission_code, created_at, user_id, user_name, user_email,
                           personnel_code, full_name, route_chain,
                           total_payment, total_funds, advance_payment, net_balance, hmac_sig
                    FROM mission_ledger
                    WHERE mission_code = ?
                    """,
                    (code,),
                ).fetchone()
            finally:
                conn.close()

            if not row:
                return f"کد یکتای «{code}» در دفتر کل سامانه یافت نشد. این فرم فاقد اعتبار است."

            (
                seq_id, m_code, created_at, rec_uid, rec_uname, rec_uemail,
                p_code, f_name, route_chain, tot_pay, tot_funds, adv_pay, net_bal, stored_sig
            ) = row

            if not is_auditor and user_info["id"] != rec_uid:
                return "شما مجوز مشاهده و ممیزی گزارش ثبت‌شده توسط سایر کاربران را ندارید."

            canonical = f"{seq_id}|{rec_uid}|{p_code}|{tot_pay}|{tot_funds}|{adv_pay}|{net_bal}"
            expected_sig = self._compute_hmac_short(canonical)
            sig_ok = hmac.compare_digest(expected_sig, stored_sig)
            status_text = "معتبر و اصیل (امضای سامانه تأیید شد)" if sig_ok else "نامعتبر (مغایرت در امضای اصالت)"

            return (
                f"### نتیجه استعلام اصالت کد یکتا: `{m_code}`\n\n"
                "| مشخصه ثبت‌شده در سرور | مقدار |\n"
                "|---|---|\n"
                f"| وضعیت اصالت | **{status_text}** |\n"
                f"| زمان صدور در سرور | {created_at} |\n"
                f"| ثبت‌کننده در سامانه | {rec_uname} ({rec_uemail}) |\n"
                f"| کد پرسنلی و نام مأمور | {p_code} — {f_name} |\n"
                f"| مسیر سفر | {route_chain} |\n"
                f"| جمع فوق‌العاده حق مأموریت | {self._fmt_rial(tot_pay)} ریال |\n"
                f"| جمع هزینه‌های جانبی قابل بازپرداخت | {self._fmt_rial(tot_funds)} ریال |\n"
                f"| علی‌الحساب پرداخت‌شده | {self._fmt_rial(adv_pay)} ریال |\n"
                f"| **مانده تسویه نهایی** | **{self._fmt_rial(net_bal)} ریال** |"
            )
        except Exception as exc:
            return f"خطا در استعلام کد یکتا: {exc}"

    # =====================================================================
    # ابزار عمومی ۵: مرجع فوری آیین‌نامه، نرخ‌ها و ضوابط اداری
    # =====================================================================
    async def get_mission_policy_rules(
        self,
        topic: str = "همه",
        __event_emitter__: Optional[Callable] = None,
    ) -> str:
        """
        استعلام فوری و دقیق متن آیین‌نامه مأموریت، جداول نرخ‌های جاری سال ۱۴۰۵، ضرایب وسیله و ساعات، مسافت شهرها و ضوابط اداری بدون نیاز به پایگاه دانش جداگانه.

        :param topic: موضوع مورد استعلام به فارسی؛ مثلاً: «همه»، «احراز و کلیات»، «حق مأموریت و مسیر»، «حضور در شرکت»، «اضافه‌کاری»، «غذا و اسکان»، «ایاب‌وذهاب و تاکسی»، «سفر گروهی»، «علی‌الحساب»، «ضوابط اداری و لغو»، «نرخ‌ها و ضرایب»، «مسافت شهرها»
        :return: متن رسمی و فارسی ضوابط و جداول مصوب سال ۱۴۰۵ (هماهنگ با تنظیمات جاری ابزار)
        """
        try:
            meals_rates = json.loads(self.valves.rates_meals_accommodation_json)
            advance_rates = json.loads(self.valves.advance_ceilings_json)

            rates_lines = [
                "| کلاس شغلی | اسکان ۱۰۰٪ (ریال) | اسکان ۵۰٪ انفرادی (ریال) | صبحانه (ریال) | ناهار (ریال) | شام (ریال) | جمع روزانه ۳ وعده | علی‌الحساب با اسکان | علی‌الحساب بدون اسکان/اسکان شرکت |",
                "|---|---:|---:|---:|---:|---:|---:|---:|---:|",
            ]
            for g in ["A", "B", "C", "D", "E", "F"]:
                if g in meals_rates and g in advance_rates:
                    mr = meals_rates[g]
                    ar = advance_rates[g]
                    acc = int(mr["accommodation"])
                    bf = int(mr["breakfast"])
                    ln = int(mr["lunch"])
                    dn = int(mr["dinner"])
                    rates_lines.append(
                        f"| {GRADE_LABELS_FA[g]} | {acc:,} | {acc // 2:,} | {bf:,} | {ln:,} | {dn:,} | {bf + ln + dn:,} | {int(ar['with_accommodation']):,} | {int(ar['without_accommodation']):,} |"
                    )

            dist_lines = [
                "| شهر مقصد | فاصله یک‌طرفه از اصفهان (کیلومتر) | رفت‌وبرگشت (کیلومتر) |",
                "|---|---:|---:|",
            ]
            for city_name, km_val in sorted(DISTANCES_FROM_ISFAHAN.items()):
                dist_lines.append(f"| {city_name} | {km_val:,} | {km_val * 2:,} |")

            sections: Dict[str, str] = {
                "احراز_و_کلیات": (
                    "### ۱. احراز مأموریت برون‌شهری و مبنای حقوق\n"
                    f"- **مبدأ پیش‌فرض:** شهر {self.valves.default_origin_city}.\n"
                    f"- **شرط احراز مأموریت برون‌شهری:** فاصله یک‌طرفه محل کار تا مقصد حداقل {int(self.valves.min_distance_km)} کیلومتر باشد، یا مأمور حداقل یک شب اقامت واقعی در مقصد داشته باشد.\n"
                    "- **مبنای حقوق:** فقط مجموع «حقوق پایه» به‌علاوه «پایه سنوات».\n"
                    f"- **نرخ روزانه:** مبنای حقوق تقسیم بر {int(self.valves.daily_denominator)} | **نرخ ساعتی مسیر:** مبنای حقوق تقسیم بر {int(self.valves.hourly_denominator)}.\n"
                    f"- **سقف ماهانه:** {self.valves.monthly_workday_warning_limit} روز کاری در ماه (هشدار).\n"
                    "- **موارد غیرمشمول:** مأموریت ساعتی/درون‌شهری، مشاغل دائم‌المأمور و پرسنل نیمه‌وقت یا پروژه‌ای (مگر با تصریح در قرارداد)."
                ),
                "حق_مأموریت_و_مسیر": (
                    "### ۲. بخش روزانه، تعطیلات و حق مسیر (تک‌مرحله‌ای و چندمرحله‌ای)\n"
                    "- **تعداد روز مبنای محاسبه:** بر اساس مدت مؤثر سفر (پس از کسر روزهای حضور در شرکت)، به ازای هر ۲۴ ساعت یا کسری از آن یک روز.\n"
                    f"- **ضریب تعطیلات رسمی و جمعه:** ضریب {self.valves.holiday_multiplier} بر اساس تقویم ۱۴۰۵.\n"
                    "- **شب اقامت واقعی:** فقط شب‌های اقامت در مقصد؛ شب داخل اتوبوس شب یا قطار شب اقامت نیست.\n"
                    "- **حق مسیر:** در سفر دوطرفه بر اساس فرمول ضربی با ضریب ترکیب وسیله (خودرو شرکت و آژانس معادل سواری ۰٫۱۷) و در سفر چندمرحله‌ای جمع حق مسیر مستقل هر مرحله."
                ),
                "حضور_در_شرکت": (
                    "### ۳. قاعده بند ۵-۴-۱-۳ و تلورانس\n"
                    "- کارمند در یک روز واحد نمی‌تواند هم‌زمان هم در شرکت حاضر باشد و هم حق مأموریت روزانه دریافت کند.\n"
                    "- در صورت حضور در شرکت در روز شروع یا بازگشت در بامداد روز کاری، آن روز حق مأموریت روزانه ندارد اما حق مسیر رفت یا برگشت به‌طور کامل پرداخت می‌شود.\n"
                    "- روزهای جمعه و تعطیل رسمی مشمول حذف روز حضور در شرکت نیستند."
                ),
                "اضافه‌کاری": (
                    "### ۴. ضابطه قطعی اضافه‌کاری در مأموریت\n"
                    "- **قاعده مطلق شرکت:** مأموریت به هیچ عنوان شامل اضافه‌کاری نمی‌شود."
                ),
                "غذا_و_اسکان": (
                    "### ۵. ضوابط تغذیه و اسکان\n"
                    "- **وعده‌های غذایی:** بر مبنای کل بازه سفر با مرزهای شامل؛ سقف به‌صورت تجمیعی روی کل سفر اعمال می‌شود و بدون فاکتور پرداخت صفر است. وعده شرکتی و صبحانه هتل کسر می‌شوند.\n"
                    f"- **اسکان:** مأموریت یک‌روزه تا {int(self.valves.one_day_no_accommodation_max_km)} کیلومتر (جز پرواز روز قبل) و روز خاتمه اسکان ندارد. اسکان شخصی انفرادی تا ۵۰٪ و اسکان شخصی گروهی پس از تقسیم بین نفرات تا ۱۰۰٪ سقف بالاترین کلاس گروه."
                ),
                "ایاب_و_ذهاب_و_تاکسی": (
                    "### ۶. ایاب‌وذهاب، خودروی شخصی و تردد درون‌شهری\n"
                    f"- **خودروی شخصی (فقط سفر تکی):** مجموع کیلومتر رفت‌وبرگشت ضربدر {self.valves.rate_per_km_rials:,} ریال. در سفر گروهی مجاز نیست.\n"
                    "- **تبصره ۵:** با خودروی شخصی یا خودروی شرکت، هزینه تاکسی درون‌شهری پرداخت نمی‌شود؛ به‌جز در تهران به‌دلیل طرح ترافیک."
                ),
                "سفر_گروهی": (
                    "### ۷. ضوابط مأموریت‌های گروهی\n"
                    "- سقف غذا و اسکان همه اعضا خودکار بر اساس بالاترین کلاس شغلی حاضر در گروه محاسبه می‌شود."
                ),
                "علی‌الحساب": (
                    "### ۸. ضوابط علی‌الحساب\n"
                    "- سقف جدول صرفاً برای تنخواه است و عبور از آن هشدار می‌دهد. مانده تسویه = جمع حق مأموریت و هزینه‌های جانبی منهای علی‌الحساب."
                ),
                "ضوابط_اداری_و_لغو": (
                    "### ۹. گردش کار، لغو و تمدید مأموریت\n"
                    "- ارائه گزارش و مدارک حداکثر ظرف ۱ روز و تسویه مالی حداکثر ظرف ۳ روز پس از پایان مأموریت. در صورت لغو، کنسل فوری بلیت و تحویل لاشه بلیت الزامی است."
                ),
                "نرخ‌ها_و_ضرایب": (
                    "### ۱۰. جدول نرخ‌های مصوب ۱۴۰۵ و ضرایب مسیر\n"
                    + "\n".join(rates_lines)
                    + "\n\n**ضرایب ساعتی:** ۰۰–۰۲: ۱٫۵۰ | ۰۲–۰۴: ۱٫۶۰ | ۰۴–۰۶: ۱٫۵۰ | ۰۶–۰۸: ۱٫۳۰ | ۰۸–۱۶: ۱٫۰۰ | ۱۶–۱۹: ۱٫۲۰ | ۱۹–۲۱: ۱٫۲۵ | ۲۱–۲۴: ۱٫۳۰."
                ),
                "مسافت_شهرها": (
                    "### ۱۱. جدول مسافت ۳۱ مرکز استان از مبدأ اصفهان\n"
                    + "\n".join(dist_lines)
                ),
            }

            q = self._norm_digits(topic).strip().lower()
            if not q or any(w in q for w in ["همه", "کامل", "کل", "all"]):
                selected = [v for k, v in sections.items() if k != "مسافت_شهرها"]
            else:
                keyword_map = [
                    ("احراز_و_کلیات", ["احراز", "کلیات", "مبنا", "حقوق", "۵۰", "50", "قرارداد", "نیمه", "پروژه", "دائم", "۱۵", "15"]),
                    ("حق_مأموریت_و_مسیر", ["مسیر", "ضریب", "ساعت", "چندمرحله", "چند مرحله", "تعطیل", "جمعه", "شب اقامت"]),
                    ("حضور_در_شرکت", ["شرکت", "۵-۴-۱-۳", "5-4-1-3", "تلورانس", "بازگشت", "یکشنبه"]),
                    ("اضافه‌کاری", ["اضافه", "overtime"]),
                    ("غذا_و_اسکان", ["غذا", "تغذیه", "صبحانه", "ناهار", "شام", "هتل", "اسکان", "اقامت", "فاکتور"]),
                    ("ایاب_و_ذهاب_و_تاکسی", ["ایاب", "ذهاب", "تاکسی", "اسنپ", "تپسی", "خودرو", "کیلومتر", "تهران", "تبصره"]),
                    ("سفر_گروهی", ["گروه", "مافوق", "همراه", "مشترک"]),
                    ("علی‌الحساب", ["علی", "الحساب", "تنخواه", "تسویه"]),
                    ("ضوابط_اداری_و_لغو", ["اداری", "گردش", "لغو", "کنسل", "تمدید", "حکم", "مالی"]),
                    ("نرخ‌ها_و_ضرایب", ["نرخ", "سقف", "جدول", "ضرایب", "کلاس", "گرید"]),
                    ("مسافت_شهرها", ["مسافت", "فاصله", "شهر", "اصفهان"]),
                ]
                selected = [sections[sk] for sk, kws in keyword_map if any(kw in q for kw in kws)]
                if not selected:
                    selected = [v for k, v in sections.items() if k != "مسافت_شهرها"]

            return "\n\n".join(selected)
        except Exception as exc:
            return f"خطا در بازیابی ضوابط آیین‌نامه: {exc}"